## Architecture: Two Modes in One Parser

The key insight is a single `rawBody` function drives **both** modes, selected by a flag on the parser object.

### 1. Register a Custom Parser

```js
// Buffered (string/Buffer result)
fastify.addContentTypeParser('application/x-custom', {
  parseAs: 'buffer',   // or 'string'
  bodyLimit: 1_048_576 // 1 MB override
}, function myParser(req, body, done) {
  try {
    done(null, JSON.parse(body)) // body is already a Buffer/string
  } catch (e) {
    done(e)
  }
})

// Streaming (raw Node stream handed to you)
fastify.addContentTypeParser('application/x-custom', function myParser(req, payload, done) {
  // payload is a readable stream — consume it yourself
  let data = ''
  payload.on('data', chunk => { data += chunk })
  payload.on('end', ()    => done(null, data))
  payload.on('error', e   => done(e))
})
```

---

### 2. How the Core `rawBody` Works (lib/content-type-parser.js:233–275)

This is the buffering path used when `parseAs` is set:

```js
function rawBody(request, reply, options, parser, done) {
  const asString = parser.asString === true          // string vs Buffer mode
  const limit = options.limit ?? parser.bodyLimit
  const contentLength = Number(request.headers['content-length'])

  // Fast-fail: reject before reading a byte
  if (contentLength > limit) {
    return done(new ERR_BODY_TOO_LARGE())
  }

  let receivedLength = 0
  let body = asString ? '' : []                      // string accumulator vs chunk array
  const payload = request[kRequestPayloadStream] || request.raw

  if (asString) payload.setEncoding('utf8')          // decode in stream, not after

  payload.on('data', onData)
  payload.on('end',  onEnd)
  payload.on('error', onEnd)
  payload.resume()                                    // unpause a paused stream

  function onData(chunk) {
    receivedLength += asString ? Buffer.byteLength(chunk) : chunk.length
    const encodedLength = payload.receivedEncodedLength ?? 0  // guards zip-bomb

    if (receivedLength > limit || encodedLength > limit) {
      payload.removeListener('data', onData)
      payload.removeListener('end',  onEnd)
      payload.removeListener('error', onEnd)
      return done(new ERR_BODY_TOO_LARGE())
    }

    asString ? (body += chunk) : body.push(chunk)
  }

  function onEnd(err) {
    if (err) return done(err)
    done(null, asString ? body : Buffer.concat(body))  // concat once at the end
  }
}
```

**Key design points:**

| Concern | How it's handled |
|---|---|
| Body-limit enforcement | Checked twice: before streaming (`content-length` header) and per-chunk (`receivedLength`) |
| Zip-bomb protection | Also checks `payload.receivedEncodedLength` (set by a `preParsing` decompressor hook) |
| Memory efficiency | Binary mode accumulates `Buffer[]` and calls `Buffer.concat()` once at `end` — avoids repeated copies |
| Stream backpressure | `payload.resume()` drains a stream that was paused by an earlier hook |
| Listener cleanup | Removes all three listeners on early error to prevent double-`done()` calls |

---

### 3. Dispatcher Pattern (streaming vs buffered)

The parser registration stores a descriptor object. At runtime, the dispatcher checks `parser.fn` signature:

```js
// lib/content-type-parser.js ~163
function run(req, reply, options, parser, done) {
  if (parser.asString || parser.asBuffer) {
    // Buffered path → rawBody() accumulates then calls parser.fn(req, body, done)
    return rawBody(req, reply, options, parser, (err, body) => {
      if (err) return done(err)
      parser.fn(req, body, done)
    })
  }
  // Streaming path → pass raw stream directly
  parser.fn(req, req[kRequestPayloadStream] || req.raw, done)
}
```

---

### 4. Minimal Self-Contained Implementation

```js
class ContentTypeParser {
  #parsers = new Map()

  add(contentType, opts, fn) {
    if (typeof opts === 'function') { fn = opts; opts = {} }
    this.#parsers.set(contentType, {
      fn,
      asString: opts.parseAs === 'string',
      asBuffer: opts.parseAs === 'buffer',
      bodyLimit: opts.bodyLimit ?? 1_048_576
    })
  }

  run(contentType, req, reply, done) {
    const parser = this.#parsers.get(contentType)
      ?? this.#parsers.get('*')   // wildcard fallback
    if (!parser) return done(new Error(`No parser for ${contentType}`))

    if (parser.asString || parser.asBuffer) {
      this.#buffer(req, parser, (err, body) => {
        if (err) return done(err)
        parser.fn(req, body, done)
      })
    } else {
      parser.fn(req, req, done)   // raw stream
    }
  }

  #buffer(req, parser, done) {
    const limit = parser.bodyLimit
    let received = 0
    const chunks = []

    req.on('data', chunk => {
      received += chunk.length
      if (received > limit) {
        req.destroy()
        return done(new Error('Body too large'))
      }
      chunks.push(chunk)
    })
    req.on('end',   ()  => {
      const buf = Buffer.concat(chunks)
      done(null, parser.asString ? buf.toString('utf8') : buf)
    })
    req.on('error', done)
  }
}
```

---

### Summary of the Pattern

```
addContentTypeParser(type, opts, fn)
         │
         ├── opts.parseAs set?
         │      YES → rawBody() buffers chunks → calls fn(req, Buffer|string, done)
         │      NO  → fn(req, ReadableStream, done)   ← you drain it
         │
         └── body-limit guard at two levels:
                1. content-length header (pre-read, fast-fail)
                2. per-chunk accumulator (streaming, catches lies)
```

The `Buffer.concat(chunks)` at `end` (not during `data`) is the canonical Node.js pattern to avoid O(n²) string concatenation with binary data — only the string path does `body += chunk` because V8 optimises string rope concatenation well.

